/* Localized display prices only. Never use these values to authorize a payment. */
window.localPricing=(()=>{
 const labels={
  es:{currency:'Moneda',auto:'Automática · país por IP',loading:'Consultando la moneda y los precios…',detected:'País aproximado por IP',manual:'Moneda elegida',unknown:'No se pudo identificar la moneda por IP. Mostramos BRL; puedes elegir otra moneda.',unavailable:'No se pudo obtener una cotización reciente para esta moneda. Mostramos los precios originales en BRL.',estimated:'Conversión aproximada de los precios-base en BRL. No es una cotización de cobro.',base:'Precios-base en reales brasileños.',demo:'Demostración: no se realizan cobros.',updated:'Cotización del',from:'Desde',cancel:'Cancela antes de la próxima renovación',privacyTitle:'País y moneda',privacy:'Utilizamos el país aproximado que la red de alojamiento deduce de tu IP para sugerir una moneda. Esta función no almacena tu IP ni la envía al proveedor de cotizaciones. Una elección manual se guarda en este navegador y en la dirección de la página. Las cotizaciones se consultan desde el servidor. VPN y redes compartidas pueden alterar el país detectado.',terms:'Los precios-base son en BRL. Se muestran conversiones orientativas a la moneda seleccionada; esta demostración no cobra ni garantiza una cotización futura. La moneda y el importe definitivos deberán confirmarse antes de cualquier pago real.'},
  en:{currency:'Currency',auto:'Automatic · country by IP',loading:'Checking your currency and prices…',detected:'Approximate country from IP',manual:'Selected currency',unknown:'Your currency could not be identified by IP. Showing BRL; you can choose another currency.',unavailable:'A recent exchange rate is unavailable for this currency. Showing the original BRL prices.',estimated:'Approximate conversion of BRL base prices. This is not a payment quote.',base:'Base prices in Brazilian reais.',demo:'Demo: no payments are taken.',updated:'Exchange rate dated',from:'From',cancel:'Cancel before your next renewal',privacyTitle:'Country and currency',privacy:'We use the approximate country inferred from your IP by the hosting network to suggest a currency. This feature does not store your IP or send it to the exchange-rate provider. A manual choice is saved in this browser and in the page URL. Rates are fetched on the server. VPNs and shared networks can affect the detected country.',terms:'Base prices are in BRL. Indicative conversions are shown in your selected currency; this demo does not charge money or guarantee a future exchange rate. The final currency and amount must be confirmed before any real payment.'},
  pt:{currency:'Moeda',auto:'Automática · país pelo IP',loading:'Consultando a moeda e os preços…',detected:'País aproximado pelo IP',manual:'Moeda escolhida',unknown:'Não foi possível identificar a moeda pelo IP. Exibimos BRL; você pode escolher outra moeda.',unavailable:'Não foi possível obter uma cotação recente para esta moeda. Exibimos os preços originais em BRL.',estimated:'Conversão aproximada dos preços-base em BRL. Não é uma cotação de cobrança.',base:'Preços-base em reais brasileiros.',demo:'Demonstração: nenhuma cobrança é realizada.',updated:'Cotação de',from:'A partir de',cancel:'Cancele antes da próxima renovação',privacyTitle:'País e moeda',privacy:'Usamos o país aproximado que a rede de hospedagem identifica pelo seu IP para sugerir uma moeda. Esta função não armazena seu IP nem o envia ao fornecedor de cotações. A escolha manual é salva neste navegador e no endereço da página. As cotações são consultadas pelo servidor. VPNs e redes compartilhadas podem alterar o país identificado.',terms:'Os preços-base são em BRL. São exibidas conversões indicativas na moeda selecionada; esta demonstração não cobra nem garante uma cotação futura. A moeda e o valor definitivos deverão ser confirmados antes de qualquer pagamento real.'}
 };
 const escape=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const valid=v=>v==='auto'||/^[A-Z]{3}$/.test(v||'');
 let stored;try{stored=localStorage.getItem('entrega.currency')}catch{}
 const query=new URLSearchParams(location.search).get('currency');
 let preference=valid(query)?query:valid(stored)?stored:'auto', quote=null, pending=true, sequence=0;
 const fallback=()=>({currency:'BRL',country:null,source:'fallback',reason:'rates-unavailable',available:['BRL'],amounts:{0:0,29:29,79:79,290:290,790:790,50:50,500:500},estimated:false,updatedAt:null});
 const locale=lang=>({es:'es-ES',en:'en-US',pt:'pt-BR'}[lang]||'es-ES');
 function format(value,lang){if(pending||!quote)return '…';return new Intl.NumberFormat(locale(lang),{style:'currency',currency:quote.currency,currencyDisplay:'code'}).format(quote.amounts[value]??0)}
 function note(lang){const t=labels[lang];if(pending||!quote)return t.loading;return (quote.reason==='rates-unavailable'?t.unavailable:quote.reason==='country-unavailable'?t.unknown:quote.estimated?t.estimated:t.base)+' '+t.demo+(quote.updatedAt&&quote.estimated?' '+t.updated+' '+new Intl.DateTimeFormat(locale(lang),{dateStyle:'short',timeZone:'UTC'}).format(new Date(quote.updatedAt))+'.':'')}
 function selector(lang){const t=labels[lang];const names=new Intl.DisplayNames([locale(lang)],{type:'currency'});let status=pending?t.loading:quote?.source==='manual'?t.manual:quote?.source==='ip'?t.detected+': '+new Intl.DisplayNames([locale(lang)],{type:'region'}).of(quote.country):note(lang);return `<div class="currency-bar wrap"><label for="currency">${t.currency}</label><select id="currency" ${pending?'disabled':''}><option value="auto" ${preference==='auto'?'selected':''}>${t.auto}</option>${(quote?.available||['BRL']).map(code=>`<option value="${code}" ${preference===code?'selected':''}>${code} · ${escape(names.of(code))}</option>`).join('')}</select><span role="status">${escape(status)}</span></div>`}
 async function refresh(value=preference){preference=valid(value)?value:'auto';const current=++sequence;pending=true;document.dispatchEvent(new Event('pricing-change'));
  try{const r=await fetch('/api/pricing?currency='+encodeURIComponent(preference),{cache:'no-store',signal:AbortSignal.timeout(6500)});if(!r.ok)throw Error('pricing');const q=await r.json();if(!/^[A-Z]{3}$/.test(q.currency)||!Array.isArray(q.available)||q.available.some(c=>!/^[A-Z]{3}$/.test(c))||![0,29,79,290,790,50,500].every(n=>Number.isFinite(q.amounts?.[n])&&q.amounts[n]>=0))throw Error('pricing');if(current!==sequence)return;quote=q}
  catch{if(current!==sequence)return;quote=fallback()}
  pending=false;document.dispatchEvent(new Event('pricing-change'));
 }
 function select(value){try{if(value==='auto')localStorage.removeItem('entrega.currency');else localStorage.setItem('entrega.currency',value)}catch{}const u=new URL(location);u.searchParams.set('currency',value);history.replaceState(null,'',u);refresh(value)}
 function decorate(copy,lang){const t=labels[lang];return {...copy,micro:`${t.from} ${format(29,lang)}${copy.month} · ${t.cancel}`,currency:note(lang),zero:format(0,lang)+' · '+t.demo}}
 function legal(copy){for(const [lang,c] of Object.entries(copy)){c.privacySections.push([labels[lang].privacyTitle,labels[lang].privacy]);c.termsSections[1][1]=labels[lang].terms}}
 return {get preference(){return preference},get ready(){return !pending},format,note,selector,refresh,select,decorate,legal};
})();
